package com.configmonitor.app;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import org.json.*;
public class AlertScheduleTest {
 final TimeZone utc=TimeZone.getTimeZone("UTC");
 long at(String s){return java.time.Instant.parse(s+":00Z").toEpochMilli();}
 AlertSchedule.Window w(String s,int days,int start,int end){return AlertSchedule.window(true,true,days,start,end,0,at(s),utc);}
 @Test public void defaultsPermitAndMasterSwitchWins(){long now=at("2026-10-25T12:00");assertTrue(AlertSchedule.window(true,false,127,480,1380,0,now,utc).active);assertFalse(AlertSchedule.window(false,false,127,480,1380,0,now,utc).active);assertFalse(AlertSchedule.window(false,true,127,480,1380,0,now,utc).active);}
 @Test public void startInclusiveEndExclusive(){assertFalse(w("2026-10-25T07:59",1,480,1020).active);assertTrue(w("2026-10-25T08:00",1,480,1020).active);assertTrue(w("2026-10-25T16:59",1,480,1020).active);assertFalse(w("2026-10-25T17:00",1,480,1020).active);}
 @Test public void selectedDaysOnly(){assertTrue(w("2026-10-25T12:00",1,480,1020).active);assertFalse(w("2026-10-26T12:00",1,480,1020).active);assertTrue(w("2026-10-31T12:00",64,480,1020).active);}
 @Test public void overnightBelongsToStartingDay(){assertFalse(w("2026-10-25T06:00",1,1320,420).active);assertTrue(w("2026-10-25T22:00",1,1320,420).active);assertTrue(w("2026-10-26T06:59",1,1320,420).active);assertFalse(w("2026-10-26T07:00",1,1320,420).active);assertFalse(w("2026-10-26T22:00",1,1320,420).active);assertEquals(at("2026-10-25T22:00"),w("2026-10-26T06:00",1,1320,420).since);}
 @Test public void overnightWrapsWeekAndMonth(){assertTrue(w("2026-11-01T06:00",64,1320,420).active);assertEquals(at("2026-10-31T22:00"),w("2026-11-01T06:00",64,1320,420).since);}
 @Test public void usesDeviceTimeZone(){long now=at("2026-10-25T04:30");assertTrue(AlertSchedule.window(true,true,1,480,1020,0,now,TimeZone.getTimeZone("Asia/Tehran")).active);assertFalse(AlertSchedule.window(true,true,1,480,1020,0,now,utc).active);}
 @Test public void springClockChangeUsesLocalWallClock(){long now=at("2026-03-08T08:30");AlertSchedule.Window window=AlertSchedule.window(true,true,1,60,300,0,now,TimeZone.getTimeZone("America/New_York"));assertTrue(window.active);assertEquals(at("2026-03-08T06:00"),window.since);}
 @Test public void changesRequireFreshResult(){long now=at("2026-10-25T12:00");assertEquals(now,AlertSchedule.window(true,true,1,480,1020,now,now,utc).since);assertEquals(now,AlertSchedule.window(true,false,1,480,1020,now,now,utc).since);}
 @Test public void invalidSchedulesFailClosed(){for(int[] values:new int[][]{{0,480,1020},{128,480,1020},{1,-1,1020},{1,480,1440},{1,480,480}}){assertFalse(AlertSchedule.window(true,true,values[0],values[1],values[2],0,at("2026-10-25T12:00"),utc).active);try{AlertSchedule.validate(true,values[0],values[1],values[2]);fail();}catch(IllegalArgumentException expected){}}}
 JSONObject incident(long checked)throws Exception {JSONObject n=Parser.j("enabled",true,"lastCheck",checked);for(int i=0;i<6;i++)Rules.apply(n,false,-1,checked,6);return n;}
 @Test public void noDeliveryOutsideWindowOrFromOldResults()throws Exception {long now=at("2026-10-25T12:00");JSONObject n=incident(now-1);assertFalse(AlertSchedule.deliver(n,new AlertSchedule.Window(false,0),now));assertFalse(AlertSchedule.deliver(n,new AlertSchedule.Window(true,now),now));n.put("lastCheck",now);assertTrue(AlertSchedule.deliver(n,new AlertSchedule.Window(true,now),now));}
 @Test public void enabledWindowPreservesAckSnoozeAndThreshold()throws Exception {long now=at("2026-10-25T12:00");AlertSchedule.Window window=new AlertSchedule.Window(true,now);JSONObject n=incident(now);Rules.acknowledge(n);for(int i=1;i<6;i++){Rules.apply(n,false,-1,now+i,6);n.put("lastCheck",now+i);assertFalse(AlertSchedule.deliver(n,window,now+i));}Rules.apply(n,false,-1,now+6,6);n.put("lastCheck",now+6);assertTrue(AlertSchedule.deliver(n,window,now+6));n.put("snoozeUntil",now+100);assertFalse(AlertSchedule.deliver(n,window,now+7));}
 @Test public void backupKeepsScheduleAndMigratesLegacy()throws Exception {JSONObject doc=Parser.j("format",1,"nodes",new JSONArray(),"settings",new JSONObject());JSONObject settings=Backups.validate(doc).settings;assertTrue(settings.getBoolean("alertsEnabled"));assertFalse(settings.getBoolean("alertScheduleEnabled"));doc.put("settings",Parser.j("alertsEnabled",false,"alertScheduleEnabled",true,"alertDays",64,"alertStart",1320,"alertEnd",420));settings=Backups.validate(doc).settings;assertFalse(settings.getBoolean("alertsEnabled"));assertTrue(settings.getBoolean("alertScheduleEnabled"));assertEquals(64,settings.getInt("alertDays"));assertEquals(1320,settings.getInt("alertStart"));assertEquals(420,settings.getInt("alertEnd"));}
 @Test(expected=IllegalArgumentException.class) public void backupRejectsInvalidSchedule()throws Exception {Backups.validate(Parser.j("format",1,"nodes",new JSONArray(),"settings",Parser.j("alertScheduleEnabled",true,"alertDays",0)));}
}
